import {digest,HARNESS_REPOSITORY,type PublicationInput} from '../../src/change-contract';
import type {Journal,Record as PublicationRecord} from '../../services/change-publisher/core';
const op=(n:number)=>n.toString(16).padStart(64,'0');
export async function input(id=op(99)):Promise<PublicationInput>{const patch='fixture patch';return {id,session:'1',workspaceId:'aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa',artifactId:op(55),title:'Fix a harness tool contract',patch,source:{repository:HARNESS_REPOSITORY,baseRevision:'b'.repeat(40),treeSha:'c'.repeat(40),patchSha256:await digest(patch),checks:['test','typecheck','build'].map((check,i)=>({check:check as any,runId:op(i+1),treeSha:'c'.repeat(40),exitCode:0,finishedAt:i+1}))}};}
export function memoryJournal():Journal & {rows:Map<string,PublicationRecord>}{const rows=new Map<string,PublicationRecord>();return {rows,get:id=>structuredClone(rows.get(id)),reserve:r=>{if(!rows.has(r.input.id))rows.set(r.input.id,structuredClone(r));return structuredClone(rows.get(r.input.id)!);},put:r=>{const old=rows.get(r.input.id);if(!old||old.version!==r.version||old.fingerprint!==r.fingerprint)return false;r.version++;rows.set(r.input.id,structuredClone(r));return true;}};}
